effect.shader:
void main(){
vec2 res = acScreenSize;
vec2 fragCoord = acScreenNorm * res;
vec2 uv = fragCoord / res;
float pr = progress * (1.0 + crossfadeLength) - crossfadeLength;
if (invert) {
pr = 1.0 - (progress * (1.0 + crossfadeLength) - crossfadeLength);
}
float mask = smoothstep(uv.x - crossfadeLength, uv.x, pr);
float n = fract(sin(dot(floor(uv * textureZoom * 1024.0), vec2(12.9898,78.233))) * 43758.5453);
float m = clamp(n * mask + mask, 0.0, 1.0);
vec3 a = texture2DCv(inputImg.texture, uv).rgb;
vec3 b = bgColor.rgb;
vec3 col = mix(a, b, m * bgStrength);
gl_FragColor = vec4(col, 1.0);
}
